      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferred in-vivo records consistently show low brain uptake, low brain/plasma or CSF exposure, or poor CNS penetration after systemic administration; therefore the query is predicted to lack meaningful CNS access.",
